import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.1, D: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function totalFor(items) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try {
    const res = await fetch(`http://localhost:${server.address().port}/orders`, {
      method: 'POST',
      body: JSON.stringify({ items }),
    })
    assert.equal(res.status, 201)
    return (await res.json()).total
  } finally {
    server.close()
  }
}

// Characterization tests: they pin CURRENT behavior, including quirks
// (marked "quirk"), so a refactor that changes totals is noticed.
test('sums unit price * qty across items', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 71)
})

test('no discount at or below 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
  assert.equal(await totalFor([{ sku: 'A', qty: 9 }]), 90)
})

test('10% discount applies strictly above 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 20 }]), 180)
  assert.equal(await totalFor([{ sku: 'A', qty: 50 }]), 450)
})

test('quirk: just over 100 is cheaper than exactly 100 (discount cliff)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }, { sku: 'C', qty: 1 }]), 99) // 100.1 -> 90.09 -> 90? see below
})

test('quirk: total is floored to whole euros, not rounded to cents', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 33) // 33.33 -> 33
  assert.equal(await totalFor([{ sku: 'B', qty: 5 }]), 114) // 127.5 -> 114.75 -> 114
})
EOF
npm test 2>&1 | grep -E "^# (pass|fail)|actual|expected|not ok"

